			if response.Code != http.StatusOK {
				t.Fatalf("%s: HTTP %d", path, response.Code)
			}
			if err := rendered(path, response.Body.String()); (err != nil) != (count < 3) {
				t.Fatalf("%s with %d controllers: %v", path, count, err)
			}
		}
	})
}

