func Run(ctx context.Context, args []string, output io.Writer) (err error) {
	writer := commandio.NewWriter(output)
	output = writer
	defer func() { err = errors.Join(err, writer.Err()) }()
	if err := ctx.Err(); err != nil {
		return err
	}
	if len(args) == 0 || args[0] == "help" || args[0] == "--help" || args[0] == "-h" {
		_, err := io.WriteString(commandio.NewWriter(output), usage)
		return err
	}
	if observability.UnderJournal() {
		// Runtime roles replace this logger with their own; operators keep plain output.
		logger, err := observability.NewLogger(os.Stderr, observability.LogConfig{}, nil, observability.Identity(args[0], "")...)
		if err != nil {
			return err
		}
		observability.ConfigureDefault(logger)
	}

// renderRetirement renders a lost slot's unsigned retirement request from the
// ledger and OCI; tests replace it.
var renderRetirement = func(ctx context.Context, slot, dir string) (string, error) {
	return app.RenderBreakGlassRetirementRequest(ctx, slot, dir, time.Now())
}

// localAdmittedInstall reads this host's accepted controller install; tests
// replace it.
var localAdmittedInstall = func() (bootstrapstart.AcceptedIdentity, error) {
	return bootstrapstart.NewMarkerStore().ReadIdentity()
}

func runCluster(ctx context.Context, args []string, out io.Writer) error {
	help := func(arg string) bool { return arg == "--help" || arg == "-h" || arg == "help" }
	if len(args) > 0 && !help(args[0]) && args[0] != "recover-quorum" {
		return fmt.Errorf("unknown cluster command %q", args[0])
	}
	if len(args) < 2 || help(args[0]) || help(args[1]) {
		_, err := io.WriteString(out, clusterUsage)
		return err
	}
	command, args := args[1], args[2:]
	allowed, known := recoverFlags[command]
	if !known {
		return fmt.Errorf("unknown recover-quorum command %q", command)
	}
	flags := flag.NewFlagSet("recover-quorum "+command, flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	configPath := flags.String("config", "", "survivor controller.json")
	destination := flags.String("out", "", "new absolute backup directory, or render-retirement output directory")
	backupDir := flags.String("dir", "", "backup directory to verify")
	slot := flags.String("slot", "", "lost peer slot to re-found")
	retirement := flags.String("retirement", "", "root-signed <slot>.retirement envelope")
	backup := flags.String("backup", "", "verified survivor backup directory")
	if err := flags.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			_, err := io.WriteString(out, clusterUsage)
			return err
		}
		return err
	}
	if flags.NArg() != 0 {
		return errors.New("recover-quorum takes only flags")
	}
	var unused []string
	flags.Visit(func(set *flag.Flag) {
		if !slices.Contains(allowed, set.Name) {
			unused = append(unused, "--"+set.Name)
		}
	})
	if len(unused) != 0 {
		return fmt.Errorf("recover-quorum %s does not take %s", command, strings.Join(unused, ", "))
	}
	if command == "verify-backup" {
		if *backupDir == "" {
			return errors.New("verify-backup requires --dir")
		}
		files, err := membership.VerifyBackup(*backupDir)
		if err != nil {
			return err
		}
		_, err = fmt.Fprintf(out, "backup %s verified: %d files\n", *backupDir, files)
		return err
	}
	if *configPath == "" {
		return fmt.Errorf("%s requires --config", command)
	}
	target, err := recoveryTarget(*configPath)
	if err != nil {
		return err
	}
	switch command {
	case "runbook":
		_, err := io.WriteString(out, membership.Runbook(target))
		return err
	case "preflight":
		_, err := membership.Preflight(ctx, target, out)
		return err
	}
	// Every changing command acts for the locally admitted controller, so
	// the recovery config must describe that controller before any check or
	// confirmation uses it.
	accepted, err := bindLocalAdmittedInstall(target)
	if err != nil {
		return err
	}
	switch command {
	case "backup":
		return membership.Backup(ctx, target, *destination, recoveryInput, out)
	case "render-retirement":
		if *slot == "" || *destination == "" || !filepath.IsAbs(*destination) {
			return errors.New("render-retirement requires --slot and an absolute --out directory")
		}
		if *slot == target.Slot {
			return errors.New("render-retirement cannot retire the local survivor slot")
		}
		path, err := renderRetirement(ctx, *slot, *destination)
		if err != nil {
			return fmt.Errorf("render %s retirement request: %w", *slot, err)
		}
		_, err = fmt.Fprintf(out, "wrote %s; root-sign it offline with ts-orch bootstrap sign-slot-retirement\n", path)
		return err
	default: // refound
		return refound(ctx, target, accepted, *slot, *retirement, *backup, out)
	}
}

func recoveryTarget(path string) (membership.RecoveryTarget, error) {
	cfg, err := app.LoadConfig(path)
	if err != nil {
		return membership.RecoveryTarget{}, err
	}
	embedded := cfg.NATS.Embedded
	if embedded == nil || cfg.NATS.Cell == "" || cfg.NATS.Instance == "" {
		return membership.RecoveryTarget{}, errors.New("recovery needs a controller config with an embedded broker")
	}
	// Without a fixed client and route port neither a stopped nor a
	// running broker can be established.
	if embedded.Port <= 0 || embedded.RoutePort <= 0 || embedded.Host == "" || embedded.RouteHost == "" {
		return membership.RecoveryTarget{}, errors.New("recovery needs the embedded broker's fixed client and route listeners")
	}
	return membership.RecoveryTarget{Cell: cfg.NATS.Cell, Slot: cfg.NATS.Instance, StoreDir: embedded.StoreDir,
		ClientAddress: net.JoinHostPort(embedded.Host, strconv.Itoa(embedded.Port)),
		RouteAddress:  net.JoinHostPort(embedded.RouteHost, strconv.Itoa(embedded.RoutePort))}, nil
}

// bindLocalAdmittedInstall requires the recovery config to name the cell,
// slot and broker address of the controller admitted on this host.
func bindLocalAdmittedInstall(target membership.RecoveryTarget) (bootstrapstart.AcceptedIdentity, error) {
	accepted, err := localAdmittedInstall()
	if err != nil {
		return bootstrapstart.AcceptedIdentity{}, fmt.Errorf("read the locally admitted controller: %w", err)
	}
	host, _, err := net.SplitHostPort(target.ClientAddress)
	if err != nil || !strings.EqualFold(accepted.Cell, target.Cell) || accepted.Slot != target.Slot ||
		accepted.PrimaryPrivateIP != host || accepted.Store.Directory != target.StoreDir {
		return bootstrapstart.AcceptedIdentity{}, fmt.Errorf(
			"--config describes %s/%s at %s, not the controller admitted on this host (%s/%s at %s)",
			target.Cell, target.Slot, host, accepted.Cell, accepted.Slot, accepted.PrimaryPrivateIP)
	}
	return accepted, nil
}

func recoveryFixture(t *testing.T) (string, string, string) {
	t.Helper()
	root := t.TempDir()
	store := filepath.Join(root, "nats")
	if err := os.MkdirAll(filepath.Join(store, "jetstream", "ACCOUNT", "streams", "TS_CONTROL_LOG"), 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(store, "jetstream", "ACCOUNT", "streams", "TS_CONTROL_LOG", "meta.inf"),
		[]byte("{}"), 0o600); err != nil {
		t.Fatal(err)
	}
	config := filepath.Join(root, "controller.json")
	clientPort, routePort := closedPort(t), closedPort(t)
	if err := os.WriteFile(config, []byte(`{"version":2,"nats":{"cell":"gru","instance":"controller-a","replicas":3,`+
		`"embedded":{"host":"127.0.0.1","port":`+clientPort+`,"route_host":"127.0.0.1","route_port":`+routePort+
		`,"store_dir":"`+store+`"}}}`), 0o600); err != nil {
		t.Fatal(err)
	}
	previousInstall := localAdmittedInstall
	t.Cleanup(func() { localAdmittedInstall = previousInstall })
	localAdmittedInstall = func() (bootstrapstart.AcceptedIdentity, error) {
		return bootstrapstart.AcceptedIdentity{Cell: "GRU", Slot: "controller-a", SeedSlot: "controller-a",
			PrimaryPrivateIP: "127.0.0.1", Store: identityrekey.StoreIdentity{Directory: store}}, nil
	}
	stubRefoundGuard(t, root)
	_, key, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	now := time.Now().UTC().Truncate(time.Second)
	envelope, err := bootstrap.SignSlotRetirement(bootstrap.RetirementEvidence{SchemaVersion: 1,
		DeploymentID: "0000000000DMC7WFP9VHV640EP", Cell: "GRU", Environment: "production", Role: "controller",
		Slot: "controller-b", PreviousAttempt: 1, PreviousGeneration: 1,
		PreviousResultDigest: strings.Repeat("c", 64), PriorInstanceOCID: "ocid1.instance.oc1.sa-saopaulo-1.b",
		PriorCreateKey: "founder-controller-b-key", Disposition: bootstrap.SlotRetirementDisposition,
		ObservedEvidenceDigest: strings.Repeat("e", 64), FencingAuthority: "authority-epoch-1", ObservedAt: now},
		now, now.Add(time.Hour), key)
	if err != nil {
		t.Fatal(err)
	}
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		t.Fatal(err)
	}
	retirement := filepath.Join(root, "controller-b.retirement")
	if err := os.WriteFile(retirement, wire, 0o600); err != nil {
		t.Fatal(err)
	}
	return config, retirement, root
}

// stubRefoundGuard gives refound a complete ledger and a survivor whose
// cluster view already reports controller-b current.
func stubRefoundGuard(t *testing.T, root string) membership.RefoundGuard {
	t.Helper()
	previousLedger, previousGuard, previousPoll, previousWait := refoundLedger, refoundGuard, refoundPoll, refoundWait
	t.Cleanup(func() {
		refoundLedger, refoundGuard, refoundPoll, refoundWait = previousLedger, previousGuard, previousPoll, previousWait
	})
	refoundLedger = func(context.Context) (map[string]membership.LedgerSlot, error) {
		return map[string]membership.LedgerSlot{"controller-a": {Attempt: 1, Complete: true},
			"controller-b": {Attempt: 1, Complete: true}, "controller-c": {Attempt: 1, Complete: true}}, nil
	}
	refoundGuard = membership.RefoundGuard{PendingPath: filepath.Join(root, "state", "refound-pending.json"),
		HealthPath: filepath.Join(root, "state", "cluster-health.json")}
	refoundPoll, refoundWait = time.Millisecond, time.Second
	// The survivor (metadata leader) reports b current with zero lag in a
	// view observed after the relaunch begins.
	if err := clusterhealth.WriteStatusFile(refoundGuard.HealthPath, clusterhealth.Status{
		ObservedAt: time.Now().UTC().Add(30 * time.Second), MetaLeader: "gru-1-ctl-1",
		Online: []string{"gru-1-ctl-1", "gru-1-ctl-2"}, CaughtUp: []string{"gru-1-ctl-2"}}); err != nil {
		t.Fatal(err)
	}
	return refoundGuard

func LoadConfig(path string) (Config, error) {
	if path == "" {
		return Config{}, errors.New("--config is required")
	}
	info, err := os.Stat(path)
	if err != nil {
		return Config{}, fmt.Errorf("stat config: %w", err)
	}
	if info.Size() > maxConfigBytes {
		return Config{}, errors.New("config is too large")
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}, fmt.Errorf("read config: %w", err)
	}
	cfg, err := decodeConfig(data)
	if err != nil {
		return Config{}, fmt.Errorf("parse config: %w", err)
	}
	if err := cfg.Observability.Validate(); err != nil {
		return Config{}, fmt.Errorf("observability config: %w", err)
	}
	if api := cfg.Controller.MachinesAPI; api != nil {
		if err := api.Validate(); err != nil {
			return Config{}, err
		}
	}
	return cfg, nil
}

// decodeConfig strictly decodes config bytes and keeps them as the config's wire.
func decodeConfig(data []byte) (Config, error) {
	var cfg Config
	if err := protocol.DecodeStrict(data, &cfg, maxConfigBytes); err != nil {
		return Config{}, err
	}
	if cfg.Version != ConfigVersion {
		return Config{}, fmt.Errorf("config version must be %d, got %d", ConfigVersion, cfg.Version)
	}
	cfg.wire = data
	return cfg, nil

func NewWriter(destination io.Writer) *Writer {
	return &Writer{destination: destination}
}

func (writer *Writer) Write(contents []byte) (int, error) {
	if writer.err != nil {
		return 0, writer.err
	}
	written, err := writer.destination.Write(contents)
	if err == nil && written != len(contents) {
		err = io.ErrShortWrite
	}
	writer.err = err
	return written, err
}

func (writer *Writer) Err() error { return writer.err }

// Reader checks cancellation around every read, including the final read.
// Wrapping the source prevents io.Copy from bypassing these checks through a
// source's WriterTo implementation.
func Reader(ctx context.Context, source io.Reader) io.Reader {
	return reader{ctx: ctx, source: source}
}

type reader struct {
	ctx    context.Context
	source io.Reader
}

func (reader reader) Read(contents []byte) (int, error) {
	if err := reader.ctx.Err(); err != nil {
		return 0, err
	}
	read, err := reader.source.Read(contents)
	if canceled := reader.ctx.Err(); canceled != nil {
		return read, errors.Join(err, canceled)
	}
	return read, err
}

// os.File normalizes short writes; retain the kernel result to exercise Writer.
type pipeDestination int

func (fd pipeDestination) Write(contents []byte) (int, error) {
	written, err := unix.Write(int(fd), contents)
	return max(written, 0), err
}

func commandPipe(t *testing.T) (*os.File, *os.File) {
	t.Helper()
	reader, writer, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { reader.Close(); writer.Close() })
	return reader, writer
}

// Keep File.WriteTo: Reader must prevent io.Copy from bypassing Read.
type cancelAtFileEOF struct {
	*os.File
	cancel context.CancelFunc
}

func (source cancelAtFileEOF) Read(contents []byte) (int, error) {
	n, err := source.File.Read(contents)
	if errors.Is(err, io.EOF) {
		source.cancel()
	}
	return n, err
}

func verifyTaskAssignment(task *api.Task, binding host.ContainerMaterialBinding) error {
	if task == nil || task.ID != binding.TaskID || task.ServiceID != binding.ServiceID || task.NodeID != binding.NodeID ||
		task.DesiredState != api.TaskStateRunning || task.Status.State < api.TaskStateAssigned || task.Status.State > api.TaskStateRunning {
		return ErrPending
	}
	fingerprint, err := swarmruntime.ContainerTaskFingerprint(task)
	if err != nil || fingerprint != binding.Fingerprint {
		return ErrPending
	}
	return nil
}

func verifyTaskNode(node *api.Node, binding host.ContainerMaterialBinding, architecture string) error {
	if node == nil || node.Status.State != api.NodeStatus_READY || node.Spec.Availability != api.NodeAvailabilityActive {
		return ErrPending
	}
	return verifyTaskNodeIdentity(node, binding, architecture)
}

func verifyTaskNodeIdentity(node *api.Node, binding host.ContainerMaterialBinding, architecture string) error {
	if node == nil || node.ID != binding.NodeID || node.Spec.Membership != api.NodeMembershipAccepted || node.Spec.Annotations.Name != binding.HostID ||
		node.Spec.Annotations.Labels[swarmruntime.LabelInstanceID] != binding.InstanceID ||
		node.Spec.Annotations.Labels[swarmruntime.LabelRegion] != binding.Region ||
		node.Spec.Annotations.Labels[swarmruntime.LabelExecutionScope] != "platform" ||
		node.Role != node.Certificate.Role || node.Role != node.Spec.DesiredRole || node.Certificate.CN != node.ID || node.Certificate.Status.State != api.IssuanceStateIssued ||
		node.Description == nil || node.Description.Platform == nil ||
		node.Description.Platform.OS != "linux" || node.Description.Platform.Architecture != architecture {
		return ErrPending
	}
	role := ca.WorkerRole
	if node.Role == api.NodeRoleManager {
		role = ca.ManagerRole
	} else if node.Role != api.NodeRoleWorker {
		return ErrPending
	}
	block, _ := pem.Decode(node.Certificate.Certificate)
	if block == nil || block.Type != "CERTIFICATE" {
		return ErrPending
	}
	certificate, err := x509.ParseCertificate(block.Bytes)
	now := time.Now().UTC()
	if err != nil || certificate.Subject.CommonName != node.ID || !slices.Equal(certificate.Subject.OrganizationalUnit, []string{role}) ||
		now.Before(certificate.NotBefore) || !now.Before(certificate.NotAfter) {
		return ErrPending
	}
	return nil
}

func verifyTaskRecipient(proof Profile, registration host.Registration, binding host.ContainerMaterialBinding,
	node *api.Node, controller *bootstrapstart.ControllerHostRecipient,
) error {
	if node.Role == api.NodeRoleWorker {
		if controller != nil || registration.ManagedOCI == nil || registration.ManagedOCI.InstanceID != binding.InstanceID || registration.ManagedOCI.Region != binding.Region ||
			binding.HostID != registration.ID || !entityid.Valid(registration.ID) || node.Spec.Annotations.Labels[swarmruntime.LabelHostRole] != "container" {
			return ErrPending
		}
	} else if node.Role == api.NodeRoleManager {
		if controller == nil || registration.ManagedOCI != nil || proof.specSHA256 == "" || controller.SpecSHA256() != proof.specSHA256 ||
			controller.ControllerSlot() != binding.HostID || controller.Node() != registration.Node || controller.Environment() != registration.Environment ||
			controller.InstanceID() != binding.InstanceID || controller.OCIRegion() != binding.Region || node.Status.Addr != controller.PrivateIP() {
			return ErrPending
		}
		matched := false
		for _, grant := range proof.hosts {
			if grant.Node == registration.Node && grant.Environment == registration.Environment && grant.Controller == binding.HostID &&
				grant.Controller != "" && slices.Contains(grant.Roles, proof.role) {
				matched = true
			}
		}
		if !matched || node.Spec.Annotations.Labels[swarmruntime.LabelHostRole] != "manager" {
			return ErrPending
		}
	} else {
		return ErrPending
	}
	return nil
}

func verifyAllocationRecipient(proof Profile, registration host.Registration, binding host.ContainerMaterialBinding,
	node *api.Node, architecture string, controller *bootstrapstart.ControllerHostRecipient, worker swarmruntime.VerifiedWorkerMembership,
) error {
	if err := verifyTaskRecipient(proof, registration, binding, node, controller); err != nil {
		return err
	}
	if node.Role == api.NodeRoleManager {
		if worker.NodeID() != "" {
			return ErrPending
		}
		return nil
	}
	info := worker.Info()
	if worker.Validate() != nil || worker.NodeID() != binding.NodeID || worker.RegistrationID() != registration.ID ||
		worker.InstanceID() != binding.InstanceID || worker.OCIRegion() != binding.Region || !strings.EqualFold(worker.Cell(), registration.Cell) ||
		worker.Role() != "container" || worker.Architecture() != architecture || worker.PrivateIP() != node.Status.Addr ||
		info.PublicKey != registration.PublicKey || info.NATSUserPublicKey != registration.NATSUserPublicKey || info.Generation != registration.Generation {
		return ErrPending
	}
	return nil
}

// DecodeContainer refuses unsupported runtime fields rather than silently ignoring them.
func DecodeContainer(task *api.Task) (*api.ContainerSpec, error) {
	spec, err := decodeContainer(task)
	if err != nil {
		return nil, err
	}
	if task.ServiceAnnotations.Labels[LabelRole] != FunctionWorkerRole {
		if _, err := DiskBytes(task.Spec.Resources); err != nil {
			return nil, err
		}
	}
	return spec, nil
}

func decodeContainer(task *api.Task) (*api.ContainerSpec, error) {
	if task == nil || task.ID == "" || task.ServiceID == "" || len(task.ID) > 64 || strings.IndexFunc(task.ID, func(r rune) bool {
		return !(r >= 'a' && r <= 'z' || r >= '0' && r <= '9')
	}) >= 0 {
		return nil, fmt.Errorf("invalid task identity")
	}
	g := task.Spec.GetGeneric()
	if g == nil || g.Kind != ContainerKind || g.Payload == nil || g.Payload.TypeUrl != containerTypeURL || len(g.Payload.Value) > 128<<10 {
		return nil, fmt.Errorf("unsupported container runtime payload")
	}
	spec := new(api.ContainerSpec)
	if err := spec.Unmarshal(g.Payload.Value); err != nil {
		return nil, fmt.Errorf("decode container: %w", err)
	}
	encoded, err := spec.Marshal()
	if err != nil || !bytes.Equal(encoded, g.Payload.Value) {
		return nil, fmt.Errorf("container payload contains unknown or noncanonical fields")
	}
	if err := validateContainer(spec); err != nil {
		return nil, err
	}
	for _, labels := range []map[string]string{task.Annotations.Labels, task.ServiceAnnotations.Labels} {
		if labels["terrascale.stateful"] == "true" || labels["terrascale.role"] == "terrabase" {
			return nil, fmt.Errorf("stateful execution requires qualified fencing and volume hooks")
		}
	}
	r := task.Spec.Resources
	if r == nil || r.Limits == nil || r.Limits.NanoCPUs < 10_000_000 || r.Limits.NanoCPUs > 1_000_000_000_000 || r.Limits.MemoryBytes < 16<<20 {
		return nil, fmt.Errorf("container requires positive CPU and memory limits")
	}
	disk, slot, err := containerGenericResources(r.Limits.Generic)
	if err != nil {
		return nil, err
	}
	function := task.ServiceAnnotations.Labels[LabelRole] == FunctionWorkerRole
	if function && (!slot || r.Reservations == nil || !proto.Equal(r.Limits, r.Reservations)) {
		return nil, fmt.Errorf("function worker requires one dedicated host slot and fully reserved resources")
	}
	if !function && slot || r.SwapBytes != nil || r.MemorySwappiness != nil {
		return nil, fmt.Errorf("unsupported container resource controls")
	}
	if rr := r.Reservations; rr != nil && (rr.NanoCPUs < 0 || rr.MemoryBytes < 0 || rr.NanoCPUs > r.Limits.NanoCPUs || rr.MemoryBytes > r.Limits.MemoryBytes) {
		return nil, fmt.Errorf("invalid container resource reservations")
	}
	if r.Reservations != nil {
		reservedDisk, reservedSlot, err := containerGenericResources(r.Reservations.Generic)
		if err != nil || !function && reservedSlot {
			return nil, fmt.Errorf("unsupported container resource reservations")
		}
		if disk != 0 || reservedDisk != 0 {
			if _, err := DiskBytes(r); err != nil {
				return nil, err
			}
		}
	} else if disk != 0 {
		return nil, fmt.Errorf("disk requires equal limits and reservations")
	}
	if len(task.Spec.Networks) != 0 || task.Spec.LogDriver != nil || len(task.Spec.ResourceReferences) != 0 || len(task.Networks) != 0 || len(task.Volumes) != 0 {
		return nil, fmt.Errorf("network, volume, secret and custom log attachments are unsupported")
	}
	if task.Endpoint != nil {
		reserved := task.Endpoint.Ports
		if task.Endpoint.Spec != nil {
			reserved = task.Endpoint.Spec.Ports
			if len(task.Endpoint.Ports) != 0 && !proto.Equal(&api.EndpointSpec{Ports: task.Endpoint.Ports}, &api.EndpointSpec{Ports: reserved}) {
				return nil, fmt.Errorf("assigned ports differ from service host-port reservations")
			}
		}
		ports := make(map[uint32]bool)
		for _, port := range reserved {
			if port == nil || port.Protocol != api.ProtocolTCP || port.PublishMode != api.PublishModeHost || port.PublishedPort != port.TargetPort || port.TargetPort < 1024 || port.TargetPort > 65535 || ports[port.TargetPort] {
				return nil, fmt.Errorf("container requires unique unprivileged TCP host-port reservations")
			}
			ports[port.TargetPort] = true
		}
	}
	return spec, nil
}

// DiskBytes returns the exact, fully reserved discrete disk budget.
func DiskBytes(resources *api.ResourceRequirements) (int64, error) {
	if resources == nil || resources.Limits == nil || resources.Reservations == nil || !proto.Equal(resources.Limits, resources.Reservations) {
		return 0, fmt.Errorf("disk requires equal resource limits and reservations")
	}
	disk, _, err := containerGenericResources(resources.Limits.Generic)
	if err != nil {
		return 0, err
	}
	if disk == 0 {
		return 0, fmt.Errorf("container requires one positive discrete disk budget")
	}
	return disk, nil
}

func ContainerTaskFingerprint(t *api.Task) (string, error) {
	if _, err := DecodeContainer(t); err != nil {
		return "", err
	}
	return taskFingerprint(t), nil
}

func taskFingerprint(t *api.Task) string {
	h := sha256.New()
	h.Write(t.Spec.GetGeneric().Payload.Value)
	h.Write([]byte(t.ServiceID))
	b, _ := t.Spec.Resources.Marshal()
	h.Write(b)
	if t.Endpoint != nil {
		b, _ := t.Endpoint.Marshal()
		h.Write(b)
	}
	if t.ServiceAnnotations.Labels[LabelRole] == "function-worker" {
		for _, key := range slices.Sorted(maps.Keys(t.ServiceAnnotations.Labels)) {
			fmt.Fprintf(h, "%q=%q\n", key, t.ServiceAnnotations.Labels[key])
		}
	}
	h.Write(binary.BigEndian.AppendUint64(nil, t.Spec.ForceUpdate))
	return fmt.Sprintf("%x", h.Sum(nil))
}

type Access struct {
	URLs  []string
	Token string `json:"-"`
}

func (a Access) String() string   { return fmt.Sprintf("regional read access (%d origins)", len(a.URLs)) }
func (a Access) GoString() string { return a.String() }

func resolveCurrent(ctx context.Context, resolver region.FoundationResolver, selector string,
	bundles func(string) (vaultsecret.BundleClient, error),
) (Access, error) {
	if selector != "" {
		entry, ok := catalog.CellForOCIRegion(selector)
		if !ok {
			entry, ok = catalog.Lookup(strings.ToUpper(selector))
		}
		if !ok {
			return Access{}, errors.New("read access region is outside the catalog")
		}
		selector = entry.Cell
	}
	access, err := resolver.ReadAccess(ctx, selector)
	if err != nil {
		if ctx.Err() != nil {
			return Access{}, ctx.Err()
		}
		if errors.Is(err, region.ErrReadAccessPending) || errors.Is(err, region.ErrFoundationGrantPending) {
			return Access{}, errors.Join(ErrPending, err)
		}
		return Access{}, err
	}
	client, err := bundles(access.OCIRegion())
	if err != nil {
		return Access{}, errors.New("authenticated regional Vault client is unavailable")
	}
	current, err := vaultsecret.ReadCurrent(ociclient.RequestContext(ctx), client, access.UsageToken())
	if err != nil {
		if ctx.Err() != nil {
			return Access{}, ctx.Err()
		}
		if vaultsecret.Absent(err) {
			return Access{}, fmt.Errorf("%w: signed regional usage token is absent", ErrPending)
		}
		return Access{}, err
	}
	if err := ctx.Err(); err != nil {
		return Access{}, err
	}
	if !access.IsVerified() {
		return Access{}, errors.New("signed read access expired during discovery")
	}
	token := current.Value()
	if len(token) < 32 || len(token) > 4096 {
		return Access{}, errors.New("regional usage token has an invalid bearer length")
	}
	for i := range len(token) {
		if token[i] <= ' ' || token[i] >= 127 {
			return Access{}, errors.New("regional usage token has invalid bearer bytes")
		}
	}
	return Access{URLs: access.URLs(), Token: token}, nil
}

func validateReadAccess(intent ReadAccessIntent, target vaultsecret.Target) error {
	if intent.UsageToken.Vault != target.VaultID || len(intent.UsageToken.Name) > 255 || !readAccessSecretName.MatchString(intent.UsageToken.Name) || len(intent.URLs) == 0 || len(intent.URLs) > 64 {
		return errors.New("signed read access lacks exact owned Vault references or bounded origins")
	}
	seen := make(map[string]bool, len(intent.URLs))
	for _, origin := range intent.URLs {
		u, err := url.Parse(origin)
		if err != nil || len(origin) > 2048 || u.Scheme != "https" || u.Hostname() == "" || u.User != nil || u.Opaque != "" || u.RawQuery != "" || u.ForceQuery || u.Fragment != "" || u.RawFragment != "" || u.Path != "" && u.Path != "/" || u.RawPath != "" || strings.ContainsAny(origin, "\r\n\t ") {
			return errors.New("signed read access requires exact HTTPS origins without credentials, paths or redirects")
		}
		if strings.HasSuffix(u.Host, ":") {
			return errors.New("signed read access has an empty port")
		}
		if port := u.Port(); port != "" {
			number, err := strconv.Atoi(port)
			if err != nil || number < 1 || number > 65535 {
				return errors.New("signed read access has an invalid port")
			}
		}
		key := strings.ToLower(u.Host)
		if seen[key] {
			return errors.New("signed read access repeats an origin")
		}
		seen[key] = true
	}
	return nil
}

func (s *SignedFootprint) AuthorizedReadAccess(ctx context.Context, cell string) (VerifiedReadAccess, error) {
	footprint, expires, err := s.authorizedRegions(ctx)
	if err != nil {
		return VerifiedReadAccess{}, err
	}
	if cell == "" {
		home, ok := catalog.CellForOCIRegion(s.home.OCIRegion)
		if !ok {
			return VerifiedReadAccess{}, errors.New("signed home region is outside the catalog")
		}
		cell = home.Cell
	}
	for _, intent := range footprint.Regions {
		if intent.Plan["cell"] != cell {
			continue
		}
		if intent.ReadAccess == nil {
			return VerifiedReadAccess{}, ErrReadAccessPending
		}
		ids, _ := intent.Plan["resource_ids"].(map[string]any)
		target := vaultsecret.Target{}
		target.CompartmentID, _ = ids["control_compartment"].(string)
		target.VaultID, _ = ids["vault"].(string)
		target.KeyID, _ = ids["key"].(string)
		entry, ok := catalog.Lookup(cell)
		if !ok || intent.Plan["region"] != entry.OCIRegion || target.CompartmentID == "" || target.KeyID == "" || !strings.HasPrefix(target.VaultID, "ocid1.vault.oc1."+entry.OCIRegion+".") || !strings.HasPrefix(target.KeyID, "ocid1.key.oc1."+entry.OCIRegion+".") {
			return VerifiedReadAccess{}, errors.New("signed read access lacks owned regional control, Vault and key identities")
		}
		if err := validateReadAccess(*intent.ReadAccess, target); err != nil {
			return VerifiedReadAccess{}, err
		}
		read := *intent.ReadAccess
		read.URLs = slices.Clone(read.URLs)
		return VerifiedReadAccess{intent: read, target: target, cell: cell, region: entry.OCIRegion, generation: intent.Generation, expires: expires}, nil
	}
	return VerifiedReadAccess{}, ErrReadAccessPending
}

// ReadAccess requires the same signed intent and its current reconciled record.
func (r FoundationResolver) ReadAccess(ctx context.Context, cell string) (VerifiedReadAccess, error) {
	reader, ok := r.Footprint.(interface {
		AuthorizedReadAccess(context.Context, string) (VerifiedReadAccess, error)
	})
	if !ok {
		return VerifiedReadAccess{}, ErrReadAccessPending
	}
	access, err := reader.AuthorizedReadAccess(ctx, cell)
	if err != nil {
		return VerifiedReadAccess{}, err
	}
	record, err := r.Resolve(ctx, access.Cell())
	if errors.Is(err, ErrFoundationMissing) {
		return VerifiedReadAccess{}, errors.Join(ErrReadAccessPending, err)
	}
	if err != nil {
		return VerifiedReadAccess{}, err
	}
	if err := ctx.Err(); err != nil {
		return VerifiedReadAccess{}, err
	}
	target, err := record.VaultTarget()
	if err != nil || target != access.target || record.Generation != access.generation || !access.IsVerified() {
		return VerifiedReadAccess{}, errors.New("read access differs from its current reconciled foundation")
	}
	return access, nil
}

func NewSignedFootprint(client FoundationObjects, anchor bootstrap.VerifiedBootstrapAnchor, roots trust.Keyring, tenancy string) (*SignedFootprint, error) {
	if client == nil {
		return nil, errors.New("foundation scope requires an authenticated object client")
	}
	return newSignedFootprint(client, anchor, roots, tenancy)
}

func newSignedFootprint(client FoundationObjects, anchor bootstrap.VerifiedBootstrapAnchor, roots trust.Keyring, tenancy string) (*SignedFootprint, error) {
	if !anchor.IsVerified() || len(roots) == 0 {
		return nil, errors.New("foundation scope requires verified bootstrap identity and roots")
	}
	home, err := anchor.FoundationScope()
	if err != nil {
		return nil, err
	}
	if tenancy != home.TenancyID {
		return nil, errors.New("authenticated tenancy differs from signed home reference")
	}
	identity := anchor.Anchor()
	return &SignedFootprint{bootstrapAnchor: anchor, client: client, storage: home.StorageDomain, expires: anchor.ExpiresAt(), home: home, local: identity,
		scope: trust.Scope{Domain: foundationGrantDomain, DeploymentID: home.DeploymentID, Cell: "GRU", Environment: identity.Environment, Role: "foundation", Slot: home.ClusterID}, roots: maps.Clone(roots), tenancy: tenancy}, nil
}

func (s *SignedFootprint) AuthorizedRegions(ctx context.Context) (ApprovedFootprint, error) {
	footprint, _, err := s.authorizedRegions(ctx)
	return footprint, err
}

func (s *SignedFootprint) authorizedRegions(ctx context.Context) (ApprovedFootprint, time.Time, error) {
	wire, err := s.readGrant(ctx)
	if err != nil {
		return ApprovedFootprint{}, time.Time{}, err
	}
	return s.verifyGrant(wire)
}

func (s *SignedFootprint) readGrant(ctx context.Context) ([]byte, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if !time.Now().Before(s.expires) {
		return nil, errors.New("foundation bootstrap authority expired")
	}
	if s.retainedGrant != nil {
		return bytes.Clone(s.retainedGrant), nil
	}
	domain := s.storage
	name := strings.TrimSuffix(domain.Prefix, "/") + "/" + foundationGrantObject
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	response, err := s.client.GetObject(ociclient.RequestContext(ctx), objectstorage.GetObjectRequest{NamespaceName: new(domain.Namespace), BucketName: new(domain.HeadBucket), ObjectName: new(name)})
	if err != nil {
		if service, ok := common.IsServiceError(err); ok && service.GetHTTPStatusCode() == 404 {
			return nil, fmt.Errorf("%w: initial tenancy authorization is absent", ErrFoundationGrantPending)
		}
		return nil, fmt.Errorf("read authenticated foundation scope: %w", err)
	}
	if response.Content == nil {
		return nil, errors.New("foundation scope object has no content")
	}
	defer response.Content.Close()
	wire, err := io.ReadAll(io.LimitReader(response.Content, foundationRecordLimit+1))
	if err != nil || len(wire) > foundationRecordLimit {
		return nil, errors.New("foundation scope object unreadable or oversized")
	}
	return wire, nil
}

func (s *SignedFootprint) verifyGrant(wire []byte) (ApprovedFootprint, time.Time, error) {
	if !time.Now().Before(s.expires) {
		return ApprovedFootprint{}, time.Time{}, errors.New("foundation bootstrap authority expired")
	}
	digest := sha256.Sum256(wire)
	if hex.EncodeToString(digest[:]) != s.home.GrantSHA256 {
		return ApprovedFootprint{}, time.Time{}, errors.New("foundation grant differs from root-pinned exact wire")
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return ApprovedFootprint{}, time.Time{}, err
	}
	payload, err := trust.VerifyCurrent(envelope, s.scope, s.roots, time.Now(), bootstrap.BootstrapAnchorTrustPolicy())
	if err != nil {
		return ApprovedFootprint{}, time.Time{}, err
	}
	if envelope.ExpiresAt.After(s.expires) {
		return ApprovedFootprint{}, time.Time{}, errors.New("foundation scope outlives bootstrap authority")
	}
	var grant FoundationGrant
	if err := json.Unmarshal(payload, &grant, json.RejectUnknownMembers(true)); err != nil {
		return ApprovedFootprint{}, time.Time{}, errors.New("foundation scope schema invalid")
	}
	if grant.InstallationID != s.home.InstallationID || (grant.SchemaVersion != 1 && grant.SchemaVersion != 2) || grant.Generation != s.home.GrantGeneration || grant.TenancyID != s.tenancy || grant.MonthlyLimitMinor <= 0 ||
		(grant.Currency != "USD" && grant.Currency != "BRL") || grant.CleanupOwner == "" || len(grant.CleanupOwner) > 128 {
		return ApprovedFootprint{}, time.Time{}, errors.New("foundation scope lacks matching tenancy, numerical spend authority or cleanup owner")
	}
	footprint := ApprovedFootprint{GrantSHA256: hex.EncodeToString(digest[:]), TenancyID: grant.TenancyID, ParentCompartmentID: grant.ParentCompartmentID,
		SharedCompartmentID: grant.SharedCompartmentID, Regions: grant.Regions}
	for _, intent := range footprint.Regions {
		if intent.Generation != grant.Generation {
			return ApprovedFootprint{}, time.Time{}, errors.New("foundation intent generation differs from signed grant")
		}
	}
	return footprint, envelope.ExpiresAt, validateFootprint(footprint)

func NewObjectFoundationStore(client FoundationObjects, namespace, bucket string) (*ObjectFoundationStore, error) {
	if client == nil || namespace == "" || bucket == "" || strings.ContainsAny(namespace+bucket, "/\\\r\n") {
		return nil, errors.New("regional foundation store requires an existing home bucket and namespace")
	}
	return &ObjectFoundationStore{client: client, namespace: namespace, bucket: bucket}, nil
}

func (s *ObjectFoundationStore) Load(ctx context.Context, cell string) (FoundationRecord, string, error) {
	if !catalog.IsCell(cell) {
		return FoundationRecord{}, "", errors.New("foundation record cell is outside catalog")
	}
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	name := foundationObjectPrefix + cell + ".json"
	response, err := s.client.GetObject(ociclient.RequestContext(ctx), objectstorage.GetObjectRequest{NamespaceName: new(s.namespace), BucketName: new(s.bucket), ObjectName: new(name)})
	if service, ok := common.IsServiceError(err); ok && service.GetHTTPStatusCode() == 404 {
		return FoundationRecord{}, "", ErrFoundationMissing
	}
	if err != nil {
		return FoundationRecord{}, "", fmt.Errorf("read regional foundation record: %w", err)
	}
	if response.Content == nil {
		return FoundationRecord{}, "", errors.New("foundation record has no content")
	}
	defer response.Content.Close()
	if response.ETag == nil || *response.ETag == "" {
		return FoundationRecord{}, "", errors.New("foundation record has no conditional-write ETag")
	}
	wire, err := io.ReadAll(io.LimitReader(response.Content, foundationRecordLimit+1))
	if err != nil {
		return FoundationRecord{}, "", err
	}
	if len(wire) > foundationRecordLimit {
		return FoundationRecord{}, "", errors.New("foundation record exceeds size bound")
	}
	var record FoundationRecord
	if err := json.Unmarshal(wire, &record, json.RejectUnknownMembers(true)); err != nil {
		return FoundationRecord{}, "", errors.New("foundation record has invalid schema")
	}
	if err := record.validate(); err != nil {
		return FoundationRecord{}, "", err
	}
	if record.Cell != cell {
		return FoundationRecord{}, "", errors.New("foundation record differs from its object key")
	}
	return record, *response.ETag, nil
}

func (r FoundationResolver) Resolve(ctx context.Context, cell string) (FoundationRecord, error) {
	if r.Footprint == nil || r.Store == nil {
		return FoundationRecord{}, errors.New("foundation discovery requires authenticated footprint and durable store")
	}
	footprint, err := r.Footprint.AuthorizedRegions(ctx)
	if err != nil {
		return FoundationRecord{}, err
	}
	if err := validateFootprint(footprint); err != nil {
		return FoundationRecord{}, err
	}
	for _, intent := range footprint.Regions {
		if intent.Plan["cell"] != cell {
			continue
		}
		record, _, err := r.Store.Load(ctx, cell)
		if err != nil {
			return FoundationRecord{}, err
		}
		digest, err := FoundationIntentDigest(intent)
		if err != nil {
			return FoundationRecord{}, err
		}
		if record.IntentDigest != digest || record.Generation != intent.Generation || record.TenancyID != footprint.TenancyID ||
			record.ParentCompartmentID != footprint.ParentCompartmentID || record.SharedCompartmentID != footprint.SharedCompartmentID || record.Stage != "reconciled" {
			return FoundationRecord{}, errors.New("authorized regional foundation is not reconciled at its current full intent; preserve the journal and follow docs/foundation-binding-recovery.md")
		}
		return record, nil
	}
	return FoundationRecord{}, errors.New("region is outside authenticated foundation footprint")
}

func (r FoundationRecord) VaultTarget() (vaultsecret.Target, error) {
	if err := r.validate(); err != nil || r.Stage != "reconciled" {
		return vaultsecret.Target{}, errors.New("Vault delivery requires a reconciled foundation record")
	}
	target := vaultsecret.Target{CompartmentID: r.ResourceIDs["control_compartment"], VaultID: r.ResourceIDs["vault"], KeyID: r.ResourceIDs["key"]}
	for kind, id := range map[string]string{"compartment": target.CompartmentID, "vault": target.VaultID, "key": target.KeyID} {
		parts := strings.Split(id, ".")
		if len(parts) < 5 || parts[0] != "ocid1" || parts[1] != kind || parts[2] != "oc1" || kind != "compartment" && parts[3] != r.OCIRegion {
			return vaultsecret.Target{}, errors.New("foundation Vault target has invalid resource scope")
		}
		for _, c := range id {
			if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '.' || c == '-') {
				return vaultsecret.Target{}, errors.New("foundation Vault target has invalid resource identity")
			}
		}
	}
	return target, nil
}

type FoundationIntent struct {
	Generation        uint64                   `json:"generation"`
	Plan              map[string]any           `json:"plan"`
	BootstrapMaterial *BootstrapMaterialIntent `json:"bootstrapMaterial,omitempty"`
	ReadAccess        *ReadAccessIntent        `json:"readAccess,omitempty"`
	NetBirdManager    *NetBirdManagerIntent    `json:"netbirdManager,omitempty"`
}

// FoundationIntentDigest binds every signed authority field to its generation.
func FoundationIntentDigest(intent FoundationIntent) (string, error) {
	wire, err := json.Marshal(intent, json.Deterministic(true))
	if err != nil {
		return "", err
	}
	// Independent verifiers read the signed JSON as objects, so normalize struct
	// field order to the same recursively sorted representation before hashing.
	var object map[string]any
	if err := json.Unmarshal(wire, &object); err != nil {
		return "", err
	}
	wire, err = json.Marshal(object, json.Deterministic(true))
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(wire)
	return hex.EncodeToString(sum[:]), nil
}

func validateFootprint(f ApprovedFootprint) error {
	if !strings.HasPrefix(f.TenancyID, "ocid1.tenancy.") || !strings.HasPrefix(f.ParentCompartmentID, "ocid1.compartment.") ||
		!strings.HasPrefix(f.SharedCompartmentID, "ocid1.compartment.") || len(f.Regions) == 0 || len(f.Regions) > len(catalog.Entries()) {
		return errors.New("authorized regional footprint lacks tenancy, compartments or reviewed regions")
	}
	seen := map[string]bool{}
	for _, intent := range f.Regions {
		p := intent.Plan
		cell, _ := p["cell"].(string)
		entry, ok := catalog.Lookup(cell)
		if !ok || seen[cell] || intent.Generation == 0 || p["region"] != entry.OCIRegion ||
			p["tenancy_id"] != f.TenancyID || p["parent_compartment_id"] != f.ParentCompartmentID || p["shared_compartment_id"] != f.SharedCompartmentID {
			return errors.New("regional plan is outside authenticated footprint or repeats a region")
		}
		if _, ok := p["resource_ids"].(map[string]any); !ok {
			return errors.New("regional plan lacks resource identities")
		}
		seen[cell] = true
	}
	return nil
}

func ReadCurrent(ctx context.Context, client BundleClient, ref Ref) (Current, error) {
	if ref.region() == "" || len(ref.Name) > 255 || !nameRE.MatchString(ref.Name) {
		return Current{}, errors.New("Vault current read requires a regional Vault and a secret name")
	}
	bundle, err := readBundle(ctx, client, ref.Vault, ref.Name)
	if err != nil {
		return Current{}, err
	}
	if bundle.SecretId == nil || !secretOCIDRE.MatchString(*bundle.SecretId) ||
		strings.Split(*bundle.SecretId, ".")[3] != ref.region() ||
		bundle.VersionNumber == nil || *bundle.VersionNumber < 1 ||
		bundle.TimeOfExpiry != nil && !time.Now().Before(bundle.TimeOfExpiry.Time) ||
		bundle.TimeOfDeletion != nil && !time.Now().Before(bundle.TimeOfDeletion.Time) {
		return Current{}, fmt.Errorf("Vault secret %s returned invalid or expired version metadata", ref.Name)
	}
	value, err := decodeBundle(bundle.SecretBundle, ref.Name)
	if err != nil {
		return Current{}, err
	}
	expires := time.Time{}
	for _, deadline := range []*common.SDKTime{bundle.TimeOfExpiry, bundle.TimeOfDeletion} {
		if deadline != nil && (expires.IsZero() || deadline.Time.Before(expires)) {
			expires = deadline.Time
		}
	}
	return Current{ID: *bundle.SecretId, Version: *bundle.VersionNumber, ExpiresAt: expires, value: value}, nil
}

func readBundle(ctx context.Context, client BundleClient, vaultID, name string) (ocisecrets.GetSecretBundleByNameResponse, error) {
	if err := safeEnv(); err != nil {
		return ocisecrets.GetSecretBundleByNameResponse{}, err
	}
	response, err := client.GetSecretBundleByName(ctx, ocisecrets.GetSecretBundleByNameRequest{
		SecretName: new(name), VaultId: new(vaultID), Stage: ocisecrets.GetSecretBundleByNameStageCurrent,
	})
	if err != nil {
		return response, &readError{name: name, cause: err}
	}
	return response, nil
}

// Keep the SDK error available for retry classification, without printing
// a response body that might contain secret material.
type readError struct {
	name  string
	cause error
}

func (e *readError) Error() string    { return "read Vault secret " + e.name + " failed" }
func (e *readError) Unwrap() error    { return e.cause }
func (e *readError) GoString() string { return e.Error() }

func decodeBundle(bundle ocisecrets.SecretBundle, name string) (string, error) {
	var content *string
	switch bundle := bundle.SecretBundleContent.(type) {
	case ocisecrets.Base64SecretBundleContentDetails:
		content = bundle.Content
	case *ocisecrets.Base64SecretBundleContentDetails:
		if bundle != nil {
			content = bundle.Content
		}
	}
	if content == nil {
		return "", fmt.Errorf("Vault secret %s has no base64 content", name)
	}
	if len(*content) > base64.StdEncoding.EncodedLen(maxValue) {
		return "", fmt.Errorf("Vault secret %s exceeds %d bytes", name, maxValue)
	}
	value, err := base64.StdEncoding.Strict().DecodeString(*content)
	if err != nil {
		return "", fmt.Errorf("Vault secret %s is not base64", name)
	}
	if len(value) > maxValue {
		return "", fmt.Errorf("Vault secret %s exceeds %d bytes", name, maxValue)
	}
	return string(value), nil

func SecretsClient(factory *ociclient.Factory) (ocisecrets.SecretsClient, error) {
	client, err := ocisecrets.NewSecretsClientWithConfigurationProvider(factory.Provider())
	if err != nil {
