func (current view) historyRange(metric string, labels map[string]string, nameBy string, rate bool) []chartSeries {
	if current.Journal == nil || current.Journal.History == nil {
		return nil
	}
	result := current.Journal.History.Range(observability.HistoryQuery{Metric: metric, Labels: labels,
		Start: current.Now.Add(-current.State.Range.Duration), End: current.Now, Rate: rate, MaxSeries: 64})
	return historyChartSeries(result, metric, nameBy)
}

func historyChartSeries(result observability.HistoryResult, metric, nameBy string) []chartSeries {
	series := make([]chartSeries, 0, len(result.Series))
	for _, found := range result.Series {
		if len(found.Points) == 0 {
			continue
		}
		name := seriesName(found.Labels, nameBy)
		if name == "" {
			name = metric
		}
		points := make([][2]float64, 0, len(found.Points))
		for _, point := range found.Points {
			value := point.Value
			if metric == observability.HistNATSRouteRTT {
				value = point.Max
			}
			if math.IsNaN(value) || math.IsInf(value, 0) {
				continue
			}
			if metric != observability.HistNATSRouteRTT {
				value = round(value)
			}
			points = append(points, [2]float64{float64(point.Time.UnixMilli()), value})
		}
		series = append(series, chartSeries{Name: name, Points: points})
	}
	slices.SortFunc(series, func(left, right chartSeries) int { return cmp.Compare(left.Name, right.Name) })
	return series
}

// seriesName names a series by one label, or by several comma-separated
// labels joined with " / " (consumers are only unique within their stream).
func seriesName(labels map[string]string, nameBy string) string {
	if !strings.Contains(nameBy, ",") {
		return labels[nameBy]
	}
	var parts []string
	for name := range strings.SplitSeq(nameBy, ",") {
		if value := labels[name]; value != "" {
			parts = append(parts, value)
		}
	}
	return strings.Join(parts, " / ")
}

func (current view) resourceNodes() []regionview.Node {
	for _, summary := range current.topologySummaries() {
		if summary.Region != current.localRegion() {
			continue
		}
		nodes := slices.Clone(summary.Nodes)
		for index := range nodes {
			nodes[index].Resources = current.resourcesForNode(nodes[index], true)
		}
		return nodes
	}
	return nil
}
